#include <iostream>
#include <vector>

using namespace std;

/**
 * GPE 10500: Brick Wall Patterns
 * 這是一個經典的費氏數列問題。
 * 長度為 N 的牆，可以由最後一塊是直放（寬度 1）或橫放（寬度 2，兩塊疊加）組成。
 * 令 f(n) 為長度 n 的方法數，則 f(n) = f(n-1) + f(n-2)。
 * f(1) = 1, f(2) = 2。
 */

int main() {
    long long f[51];
    f[1] = 1;
    f[2] = 2;
    for (int i = 3; i <= 50; ++i) {
        f[i] = f[i - 1] + f[i - 2];
    }

    int n;
    while (cin >> n && n != 0) {
        cout << f[n] << endl;
    }
    return 0;
}
